//! Tests for the imagination feed.
//!
//! Every rule here is answerable from a constructed sequence — no GPU, no model, no microphone, no
//! clock. That is the whole reason the crate is pure.

use super::*;

fn entry(id: &str, at: i64) -> Entry {
    Entry {
        id: id.to_string(),
        at_unix_ms: at,
        transcript: format!("said at {at}"),
        scene: None,
        image: format!("{id}.png"),
        tier: Tier::Reflex,
        render_ms: 205,
    }
}

// ── the dial ──────────────────────────────────────────────────────────────────────────────────

#[test]
fn every_tier_is_square_and_gets_more_steps_as_it_thinks_harder() {
    let tiers = [Tier::Reflex, Tier::Considered, Tier::Deliberate];
    for t in tiers {
        let r = t.render();
        assert_eq!(r.width, r.height, "{t:?} is not square");
    }
    // Strictly increasing effort. If this ever inverts, "think harder" would draw FEWER steps.
    let steps: Vec<u32> = tiers.iter().map(|t| t.render().steps).collect();
    assert!(steps.windows(2).all(|w| w[0] < w[1]), "steps not strictly increasing: {steps:?}");
    let cost: Vec<u32> = tiers.iter().map(|t| t.measured_ms()).collect();
    assert!(cost.windows(2).all(|w| w[0] < w[1]), "measured cost not increasing: {cost:?}");
}

#[test]
fn no_tier_renders_below_the_size_where_composition_collapses() {
    // 256² measured FASTER (128 ms) and is deliberately not a tier: SD-Turbo is trained at 512 and
    // the picture becomes an unreadable smear below roughly 384. This pins the reason, so a future
    // "cheaper tier" cannot be added by looking only at the clock.
    for t in [Tier::Reflex, Tier::Considered, Tier::Deliberate] {
        assert!(
            t.render().width >= 384,
            "{t:?} renders at {}px — below the size where SD-Turbo stays coherent",
            t.render().width
        );
    }
}

#[test]
fn listening_is_the_default_and_the_cheapest_tier() {
    assert_eq!(Tier::default_tier(), Tier::Reflex);
    assert_eq!(choose_tier(&Cue::default()), Tier::Reflex);
    // Ordering is what lets a caller compare tiers; Reflex must be the minimum.
    assert_eq!([Tier::Deliberate, Tier::Reflex, Tier::Considered].iter().min(), Some(&Tier::Reflex));
}

#[test]
fn arousal_raises_the_tier_at_its_documented_thresholds() {
    let at = |z: f32| choose_tier(&Cue { arousal_z: z, seconds: 10.0, live: true });
    assert_eq!(at(0.0), Tier::Reflex);
    assert_eq!(at(AROUSAL_CONSIDERED - 0.01), Tier::Reflex, "just below the threshold must not lift");
    assert_eq!(at(AROUSAL_CONSIDERED), Tier::Considered, "the threshold is inclusive");
    assert_eq!(at(AROUSAL_DELIBERATE - 0.01), Tier::Considered);
    assert_eq!(at(AROUSAL_DELIBERATE), Tier::Deliberate);
    assert_eq!(at(9.9), Tier::Deliberate, "nothing above the top tier");
}

#[test]
fn playback_never_earns_more_than_a_reflex() {
    // The television is not having a thought. Without this an ambient system spends its expensive
    // tier on whatever is playing in the room.
    let shouting_tv = Cue { arousal_z: 5.0, seconds: 30.0, live: false };
    assert_eq!(choose_tier(&shouting_tv), Tier::Reflex);
}

#[test]
fn a_brief_utterance_never_earns_more_than_a_reflex() {
    let clipped = Cue { arousal_z: 5.0, seconds: BRIEF_SECONDS - 0.01, live: true };
    assert_eq!(choose_tier(&clipped), Tier::Reflex);
    let just_long_enough = Cue { arousal_z: 5.0, seconds: BRIEF_SECONDS, live: true };
    assert_eq!(choose_tier(&just_long_enough), Tier::Deliberate);
}

// ── what is worth drawing ─────────────────────────────────────────────────────────────────────

#[test]
fn asrs_answers_to_silence_are_not_drawn() {
    // Measured: 5 of 23 real segments held no voice, and whisper answers silence confidently.
    for t in ["Thank you.", "thank you", "  THANK YOU.  ", "you", "Thanks for watching!", "[BLANK_AUDIO]"] {
        assert!(is_hallucination(t), "{t:?} should be recognised as a hallucination");
        assert_eq!(worth_imagining(t, None), Err(Skip::Hallucination));
    }
}

#[test]
fn a_real_sentence_containing_a_hallucination_phrase_still_counts() {
    // Whole-string, never substring — otherwise every polite sentence disappears.
    for t in ["thank you for explaining that", "I said bye and left", "you were right about the rain"] {
        assert!(!is_hallucination(t), "{t:?} was wrongly treated as a hallucination");
        assert_eq!(worth_imagining(t, None), Ok(()));
    }
}

#[test]
fn blank_and_unchanged_are_distinct_refusals() {
    assert_eq!(worth_imagining("   ", None), Err(Skip::Blank));
    assert_eq!(worth_imagining("it is raining", Some("it is raining")), Err(Skip::Unchanged));
    assert_eq!(worth_imagining("it is raining", Some("  IT IS RAINING ")), Err(Skip::Unchanged));
    assert_eq!(worth_imagining("it is raining", Some("it stopped raining")), Ok(()));
    assert_eq!(worth_imagining("it is raining", None), Ok(()));
}

// ── the bound ─────────────────────────────────────────────────────────────────────────────────

#[test]
fn the_feed_is_bounded_by_age_and_by_count_and_age_wins_first() {
    let b = Budget { max_entries: 3, max_age_ms: 1_000 };
    let now = 10_000;
    let all = vec![
        entry("fresh-a", 9_900),
        entry("fresh-b", 9_800),
        entry("fresh-c", 9_700),
        entry("fresh-d", 9_600),
        entry("stale", 8_000), // outside max_age_ms
    ];
    let kept = retain(&all, now, &b);
    assert_eq!(kept.len(), 3, "count bound not applied");
    assert!(!kept.iter().any(|e| e.id == "stale"), "an expired entry survived");
    // Newest first, and the OLDEST fresh one is the one dropped by the count bound.
    assert_eq!(kept.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(), ["fresh-a", "fresh-b", "fresh-c"]);
}

#[test]
fn an_entry_exactly_at_the_age_bound_is_kept_not_dropped() {
    let b = Budget { max_entries: 10, max_age_ms: 1_000 };
    let kept = retain(&[entry("edge", 9_000)], 10_000, &b);
    assert_eq!(kept.len(), 1, "an entry exactly at the bound must be kept");
    let gone = retain(&[entry("edge", 8_999)], 10_000, &b);
    assert!(gone.is_empty(), "one ms past the bound must be dropped");
}

#[test]
fn the_default_bound_is_shorter_than_the_ears_two_hour_window() {
    // A picture of what was said is more disclosive than the audio it came from — it reads at a
    // glance and survives in a screenshot. The asymmetry is deliberate; this pins it.
    let two_hours_ms = 2 * 60 * 60 * 1000;
    assert!(
        Budget::default().max_age_ms < two_hours_ms,
        "the imagination window must be shorter than the ear's audio window"
    );
    assert!(Budget::default().max_entries > 0);
}

#[test]
fn evicted_names_exactly_what_retain_dropped() {
    let b = Budget { max_entries: 2, max_age_ms: 1_000 };
    let now = 10_000;
    let all = vec![entry("a", 9_900), entry("b", 9_800), entry("c", 9_700), entry("old", 1_000)];
    let kept = retain(&all, now, &b);
    let gone = evicted(&all, now, &b);
    assert_eq!(kept.len() + gone.len(), all.len(), "every entry is either kept or evicted");
    for g in &gone {
        assert!(!kept.iter().any(|k| k.id == g.id), "{} is both kept and evicted", g.id);
    }
    assert_eq!(gone.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(), ["c", "old"]);
}

#[test]
fn newest_picks_by_time_not_by_position() {
    let out_of_order = vec![entry("mid", 5), entry("newest", 9), entry("oldest", 1)];
    assert_eq!(newest(&out_of_order).map(|e| e.id.as_str()), Some("newest"));
    assert_eq!(newest(&[]), None);
}

// ── the four states ───────────────────────────────────────────────────────────────────────────

#[test]
fn absent_and_empty_are_different_states_and_survive_a_round_trip() {
    // The distinction is the point: "nobody is imagining" must never render as "the room is quiet".
    let absent = FeedState::Absent;
    let empty = FeedState::Empty;
    assert_ne!(absent, empty);
    for s in [
        FeedState::Absent,
        FeedState::Empty,
        FeedState::Ready { entries: vec![entry("a", 1)] },
        FeedState::Failing { reason: "no renderer".into() },
    ] {
        let json = serde_json::to_string(&s).expect("serialises");
        let back: FeedState = serde_json::from_str(&json).expect("round-trips");
        assert_eq!(s, back, "state did not survive a round trip: {json}");
    }
}

#[test]
fn a_failing_feed_carries_its_reason() {
    let s = FeedState::Failing { reason: "no image generator on PATH".into() };
    let json = serde_json::to_string(&s).unwrap();
    assert!(json.contains("no image generator on PATH"), "the reason must survive: {json}");
    assert!(json.contains("failing"), "the tag must be the snake_case state name: {json}");
}

#[test]
fn a_scene_with_no_tier_is_absent_rather_than_reflex() {
    // "The scene stage had no opinion" and "the scene stage chose the cheapest tier" are different
    // facts, and only one of them should suppress `choose_tier`.
    let s = Scene { text: "a quiet room".into(), at_unix_ms: 1, tier: None };
    let json = serde_json::to_string(&s).unwrap();
    let back: Scene = serde_json::from_str(&json).unwrap();
    assert_eq!(back.tier, None);
    let decided: Scene = serde_json::from_str(r#"{"text":"x","at_unix_ms":1,"tier":"reflex"}"#).unwrap();
    assert_eq!(decided.tier, Some(Tier::Reflex));
}

#[test]
fn an_entry_without_a_scene_round_trips() {
    // Drawing straight from the transcript is a legitimate faster path, not a degraded one, so a
    // sceneless entry must be representable rather than needing a placeholder string.
    let e = entry("a", 1);
    assert_eq!(e.scene, None);
    let back: Entry = serde_json::from_str(&serde_json::to_string(&e).unwrap()).unwrap();
    assert_eq!(back, e);
}
